import type { PhiOverviewMockForceFlags } from '../../types';

export const PHI_OVERVIEW_MOCK_ONLY = true;

export const PHI_OVERVIEW_MOCK_FORCE_BY_SECTION: Record<
  'totalPhi' | 'phiPerformance' | 'beerEvolutionBreakdown',
  PhiOverviewMockForceFlags
> = {
  totalPhi: { skeleton: false, empty: false, error: false },
  phiPerformance: { skeleton: false, empty: false, error: false },
  beerEvolutionBreakdown: { skeleton: false, empty: false, error: false },
};

export const PHI_OVERVIEW_ERROR_TITLE_I18N_ID =
  'PortfolioBrand.PortfolioHealthIndex.Overview.errorTitle';

export const PHI_OVERVIEW_ERROR_DESCRIPTION_I18N_ID =
  'PortfolioBrand.PortfolioHealthIndex.Overview.errorDescription';

export const PHI_OVERVIEW_EMPTY_TITLE_I18N_ID =
  'PortfolioBrand.PortfolioHealthIndex.Overview.emptyTitle';

export const PHI_OVERVIEW_EMPTY_DESCRIPTION_I18N_ID =
  'PortfolioBrand.PortfolioHealthIndex.Overview.emptyDescription';
